// Facebook webhook-оос ирсэн мессежийг задлах
// Зөвхөн текст мессеж авна (echo, attachment-ийг алгасна)
const body = $input.first().json.body;
if (!body || body.object !== 'page') return [];
const out = [];
for (const entry of (body.entry || [])) {
  for (const msg of (entry.messaging || [])) {
    if (!msg.message || msg.message.is_echo || !msg.message.text) continue;
    out.push({
      json: {
        psid: String(msg.sender.id),
        text: String(msg.message.text).trim(),
      },
    });
  }
}
return out;

// Хэрэглэгчийн нэр + хайлтын үр дүнг AI Agent-д өгөх контекст болгон бэлдэнэ
const psid = $('Parse').first().json.psid;
const userText = $('Parse').first().json.text;

// Хэрэглэгчийн нэр (profile-аас)
const profile = $('Get User Profile').first().json || {};
const firstName = (profile.first_name || '').trim();

// Хайлтын үр дүн
const search = $('Search DigitalGer').first().json || {};
const products = Array.isArray(search.products) ? search.products : [];
const faqs = Array.isArray(search.faqs) ? search.faqs : [];

// Бүтээгдэхүүний мэдээллийг AI-д текстээр өгнө (matchReason оруулна — AI ойлгоход)
const fmt = (n) => Number(n).toLocaleString('mn-MN') + '₮';
const productsText = products.length
  ? products.slice(0, 5).map((p, i) => {
      const priceLine = (p.salePrice != null)
        ? `Үнэ: ${fmt(p.price)}, хямдарсан үнэ: ${fmt(p.salePrice)}`
        : `Үнэ: ${fmt(p.price)}`;
      return `${i + 1}. ${p.title}\n   Төрөл: ${p.productType}\n   ${priceLine}\n   Тайлбар: ${p.description}\n   Холбоос: ${p.url}\n   (Дотоод тэмдэглэл: ${p.matchReason})`;
    }).join('\n\n')
  : '(Бүтээгдэхүүн олдсонгүй)';

const faqsText = faqs.length
  ? faqs.slice(0, 3).map((f, i) => `${i + 1}. Асуулт: ${f.question}\n   Хариулт: ${f.answer}`).join('\n\n')
  : '(FAQ олдсонгүй)';

const nothingFound = (products.length === 0 && faqs.length === 0);

// AI Agent-д өгөх нэгдсэн оролт
const agentInput = [
  firstName ? `Хэрэглэгчийн нэр: ${firstName}` : 'Хэрэглэгчийн нэр: (тодорхойгүй)',
  ``,
  `=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===`,
  userText,
  ``,
  `=== ХАЙЛТЫН ҮР ДҮН: БҮТЭЭГДЭХҮҮН ===`,
  productsText,
  ``,
  `=== ХАЙЛТЫН ҮР ДҮН: FAQ ===`,
  faqsText,
].join('\n');

return [{
  json: {
    psid,
    userText,
    firstName,
    agentInput,
    products,
    faqs,
    hasProducts: products.length > 0,
    nothingFound,
  },
}];

// AI-ийн текст хариулт + бүтээгдэхүүний carousel card-уудыг бэлдэнэ
// FB limit: текст 2000, carousel max 10 element, title/subtitle max 80, button text max 20
const psid = $('Prep Context').first().json.psid;
const products = $('Prep Context').first().json.products || [];

// AI Agent-ийн текст хариулт
let replyText = ($input.first().json.output || '').trim();
if (!replyText) {
  replyText = 'Уучлаарай, түр алдаа гарлаа. Дахин оролдоно уу.';
}
if (replyText.length > 1900) replyText = replyText.slice(0, 1897) + '...';

// Туслах: тэмдэгт хязгаарлах
const clip = (s, n) => {
  s = String(s || '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n - 1).trim() + '…' : s;
};
// Үнийг мянгатын таслалтайгаар форматлана (locale-гүй, найдвартай)
const fmt = (n) => {
  const num = Math.round(Number(n) || 0);
  return String(num).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '₮';
};

// Carousel element-үүд (max 10)
const elements = products.slice(0, 10).map((p) => {
  // subtitle: үнэ + товч тайлбар (нийт 80 тэмдэгт)
  const priceStr = (p.salePrice != null)
    ? `${fmt(p.salePrice)} (хямд. ${fmt(p.price)})`
    : fmt(p.price);
  const descShort = clip(p.description, Math.max(0, 78 - priceStr.length - 3));
  const subtitle = clip(`${priceStr} · ${descShort}`, 80);

  const el = {
    title: clip(p.title, 80),
    subtitle: subtitle,
    default_action: {
      type: 'web_url',
      url: p.url,
      webview_height_ratio: 'full',
    },
    buttons: [
      { type: 'web_url', url: p.url, title: 'Дэлгэрэнгүй харах' },
    ],
  };
  // Зураг байвал нэмнэ (заавал биш)
  if (p.imageUrl) el.image_url = p.imageUrl;
  return el;
});

return [{
  json: {
    psid,
    replyText,
    hasCards: elements.length > 0,
    elements,
  },
}];
